var e=[{id:`n_1`,type:`scene_change`,speaker:null,text:null,stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:null,R:null}}},{id:`n_2`,type:`dialog`,speaker:`REBECCA_DELTA_NULL_NULL`,text:{KOREA:`어려운 이야기는 잘 모르겠지만... 나는 멸망을 앞둔 세계에서 아득바득 살아서 여기까지 도달한 몸이라구. 그러니까 당신이 날 믿어준다면, 나는 기꺼이 당신의 곁을 지켜주겠어. 동화 속에 나오는 기사처럼 말이야.`,JPN:`難しいことはよくわからないけど……オレは滅亡に瀕した世界で必死に生きてここまで来た奴だから。お前が信じてくれるんなら、喜んでそばで守ってやるよ。童話に出てくる騎士みたいにさ。`,ENG:`I don't know any fancy words, but... I survived all the way here from a world falling apart. So if you give me trust, I will protect you without a doubt. Like a knight from a children's books.`,TWN:`雖然我書讀得不多…但我可是在將要滅亡的世界中垂死掙扎到如今的。若是你願意相信我，那我也很樂意守護在你身旁，就像童話故事中的騎士一樣。`},stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:{char_id:`REBECCA_DELTA_NULL_NULL`,face:`UNIT_IDLE`,hologram:!1},R:null}}}];export{e as default};